'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), clamp=(x,a,b)=>Math.max(a,Math.min(b,x)), shuffle=a=>[...a].sort(()=>Math.random()-.5), pick=a=>a[Math.floor(Math.random()*a.length)], dayKey=()=>new Date().toLocaleDateString('en-CA'), fmtDate=t=>new Date(t).toLocaleDateString('pt-BR');
const STORE='archet-v1', defaults=()=>({name:'Layse',theme:'light',minutes:20,reference:440,xp:0,completed:{},attempts:[],sessions:[],journal:[],settings:{},pending:null});
function load(){try{const o=JSON.parse(localStorage.getItem(STORE));return {...defaults(),...o};}catch{return defaults()}}
let S=load(), page='home', current=null, step=0, quiz=null, practiceChecks=[], selfRating=0, lessonStart=0, lab='reading', labQ=null, expString=1, expOffset=2, tool='tuner', libraryTab='theory', pieceIndex=0, pieceSegment=0, bpm=60, meter=4, metTimer=null, metBeat=0, playing=false, seqToken=0, audioCtx=null, audioNodes=new Set(), mic=null, analyser=null, pitchFrame=0, tunerTarget='auto', recorder=null, recStream=null, recChunks=[], recUrl=null, recRecording=false, tuneSamples=[], tunerMode='free', rhythmRun=null, labEnabled=false, savedTimer=null;
function save(){try{localStorage.setItem(STORE,JSON.stringify(S));}catch{toast('Não foi possível salvar neste navegador.')}}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(savedTimer);savedTimer=setTimeout(()=>t.classList.remove('show'),2600)}
const NAMES=['Dó','Dó♯','Ré','Mi♭','Mi','Fá','Fá♯','Sol','Sol♯','Lá','Si♭','Si'], LETTERS=['C','C#','D','Eb','E','F','F#','G','G#','A','Bb','B'], OPEN=[55,62,69,76];
const name=n=>NAMES[((n%12)+12)%12], full=n=>name(n)+(Math.floor(n/12)-1), hz=n=>S.reference*2**((n-69)/12), noteLabel=n=>`${full(n)} (${LETTERS[n%12]}${Math.floor(n/12)-1})`;
const POS=[{o:0,f:'0',t:'Corda solta'},{o:1,f:'1',t:'1º dedo baixo'},{o:2,f:'1',t:'1º dedo usual'},{o:3,f:'2',t:'2º dedo baixo'},{o:4,f:'2',t:'2º dedo alto'},{o:5,f:'3',t:'3º dedo usual'},{o:6,f:'3',t:'3º dedo alto'},{o:7,f:'4',t:'4º dedo usual'},{o:8,f:'4',t:'4º dedo estendido'}];
function fingers(n){return OPEN.flatMap((o,i)=>POS.filter(x=>x.o===n-o).map(x=>({...x,string:i,note:n}))).sort((a,b)=>Number(a.f)-Number(b.f))}
function unlocked(l){let i=LESSONS.indexOf(l);return i===0||!!S.completed[LESSONS[i-1].id]||!!S.completed[l.id]}
function nextLesson(){return LESSONS.find(l=>!S.completed[l.id])||null}
function scoreSkill(k){let a=S.attempts.filter(x=>x.skill===k).slice(-30);return a.length?Math.round(a.filter(x=>x.ok).length/a.length*100):null}
function weak(){return Object.keys(SKILLS).map(k=>({k,v:scoreSkill(k),n:S.attempts.filter(a=>a.skill===k).length})).filter(x=>x.n>=3&&x.v<75).sort((a,b)=>a.v-b.v)}
function record(skill,ok,detail,source='lab'){S.attempts.push({skill,ok:!!ok,detail,source,t:Date.now()});S.attempts=S.attempts.slice(-1500);if(source==='lab') S.xp=Math.max(0,S.xp+(ok?3:-1));save()}
function level(){return Math.floor(S.xp/100)+1}function streak(){let days=new Set(S.sessions.map(x=>new Date(x.t).toDateString()));let d=new Date(),n=0;if(!days.has(d.toDateString()))d.setDate(d.getDate()-1);while(days.has(d.toDateString())){n++;d.setDate(d.getDate()-1)}return n}
function plan(){let next=nextLesson(), idx=next?LESSONS.indexOf(next):LESSONS.length, w=weak()[0], arr=[];for(let i=0;i<15;i++){let d=new Date();d.setDate(d.getDate()+i);let review=(w&&i%4===2)||(i%7===6)||idx>=LESSONS.length;if(review){let targets=LESSONS.filter(l=>S.completed[l.id]&&(!w||l.skill===w.k));let l=targets.at(-1)||LESSONS[Math.max(0,idx-1)];arr.push({d,l,review:true,skill:w?.k||l?.skill});}else{arr.push({d,l:LESSONS[idx++],review:false})}}return arr}
const NAV=[['home','⌂','Hoje'],['course','▤','Curso'],['labs','♫','Laboratórios'],['tools','◉','Ferramentas'],['progress','▥','Evolução'],['library','♧','Biblioteca']];
function go(p){stopSequence();stopMic();stopMetronome();tunerTarget='auto';guided=null;if(recRecording)stopRecording();rhythmRun=null;page=p;render();window.scrollTo(0,0)}
function btn(t,fn,cls=''){return `<button class="btn ${cls}" onclick="${fn}">${t}</button>`}
function navHtml(mobile=false){return NAV.map(([p,i,t])=>`<button class="${page===p||(page==='lesson'&&p==='course')?'active':''}" onclick="go('${p}')"><b>${i}</b>${t}</button>`).join('')}
function violinArt(){return `<svg viewBox="0 0 130 220" fill="none" aria-hidden="true"><g transform="rotate(20 65 110)" stroke="#e5c08b" stroke-width="2"><path d="M64 8c14-8 20 12 8 16l-5 42h-9l-2-42c-11-2-8-17 8-16Z"/><path d="M57 62h11l5 50H52Z" fill="#35222b"/><path d="M55 82c-17-10-35 1-30 18 2 8 12 10 12 19 0 11-15 15-16 31-2 23 22 45 43 45 23 0 45-22 43-45-1-16-16-20-16-31 0-9 10-11 12-19 5-17-13-28-30-18" fill="#a97445" fill-opacity=".5"/><path d="M53 137h22l-4 7H57Zm6 10h10l6 33H53Z"/><path d="M46 119q-12 8-4 17m40-17q12 8 4 17M60 14v160m3-160v160m3-160v160" stroke-width="1"/><path d="M110 12v190m3-190v190" stroke-width="2"/></g></svg>`}
function render(){document.body.classList.toggle('dark',S.theme==='dark');let contents=({home:homePage,course:coursePage,lesson:lessonPage,labs:labsPage,tools:toolsPage,progress:progressPage,library:libraryPage})[page]();$('#app').innerHTML=`<div class="shell"><aside class="side"><div class="brand"><div class="mark">𝄞</div><div><strong>Archet</strong><small>Estúdio de violino</small></div></div><nav class="nav">${navHtml()}</nav><div class="side-foot"><span class="pill">Nível ${level()} · ${S.xp} XP</span>${btn(S.theme==='dark'?'☀ Modo claro':'☾ Modo escuro','toggleTheme()','secondary')}</div></aside><main class="main"><div class="top"><div><span class="mobile-brand">𝄞 Archet</span><span class="eyebrow desktop-label">Estúdio pessoal · ${esc(S.name)}</span></div><div class="topright"><span class="pill">Nível ${level()} · ${S.xp} XP</span><button class="btn small secondary" aria-label="Alterar tema" onclick="toggleTheme()">${S.theme==='dark'?'☀':'☾'}</button></div></div>${contents}<div class="footer">Archet · Aprenda, escute, pratique. Seu progresso fica neste dispositivo.</div></main></div><nav class="tabbar">${navHtml(true)}</nav>`;if(page==='tools'&&tool==='tuner')updateTunerUI();if(page==='lesson'&&step===4&&tunerMode==='lesson')updateTunerUI()}
function toggleTheme(){S.theme=S.theme==='dark'?'light':'dark';save();document.body.classList.toggle('dark',S.theme==='dark');render()}
function homePage(){let n=nextLesson(),done=Object.keys(S.completed).length, w=weak()[0], pl=plan();return `<div class="hero"><div><div class="eyebrow">Seu estudo de hoje</div><h1>${esc(S.name)}, vamos tocar?</h1><p>${n?`Próxima aula: ${esc(n.title)}. Aprenda o conceito, ouça, aplique e registre sua prática.`:'Você concluiu o currículo inicial. Revise suas habilidades e amplie o repertório.'}</p><div class="actions">${n?btn('Iniciar aula →',`openLesson('${n.id}')`):btn('Revisar curso','go(\'course\')')}${btn('Explorar instrumentos de estudo','go(\'tools\')','secondary')}</div></div><div class="hero-art">${violinArt()}</div></div><div class="section grid four">${[['Aulas concluídas',`${done}/${LESSONS.length}`],['Sequência',`${streak()} dias`],['Tempo de estudo',`${S.sessions.reduce((a,s)=>a+s.minutes,0)} min`],['XP acumulado',S.xp]].map(([a,b])=>`<div class="card"><div class="muted small">${a}</div><div class="metric">${b}</div></div>`).join('')}</div><div class="section grid"><div class="card"><div class="eyebrow">Estudo inteligente</div><h3>${w?'Foco sugerido: '+SKILLS[w.k]:'Construindo a base'}</h3><p class="muted">${w?`Precisão recente de ${w.v}%: o plano intercala revisões dessa habilidade com novas aulas.`:'Conclua aulas e atividades para personalizar as próximas sessões.'}</p>${btn('Ver evolução','go(\'progress\')','secondary small')}</div><div class="card"><div class="eyebrow">Rotina sugerida</div><h3>${S.minutes} minutos por dia</h3><p class="muted">Preparação, teoria, escuta, prática e registro. O ritmo é seu: avance sem dor ou tensão.</p>${btn('Configurar rotina','go(\'progress\')','secondary small')}</div></div><div class="section"><div class="section-head"><h2>Próximos 15 dias</h2><span class="pill">Adaptativo</span></div><div class="card">${pl.map((p,i)=>`<div class="day"><div class="daynum">${i+1}</div><div><strong>${esc(p.review?'Revisão · '+(SKILLS[p.skill]||'Geral'):p.l?.title||'Repertório')}</strong><span class="muted small">${p.d.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'})} · ${p.review?'Reforço':'Nova aula'} · ${S.minutes} min</span></div>${p.l&&unlocked(p.l)?btn(p.review?'Revisar':'Abrir',`openLesson('${p.l.id}')`,'secondary small'):'<span class="tag lock">Planejado</span>'}</div>`).join('')}</div></div>`}
function coursePage(){return `<h1>Seu caminho no violino</h1><p class="muted">${LESSONS.length} aulas autorais, organizadas em ${MODULES.length} módulos. As próximas aulas são liberadas após teoria, teste e prática.</p><div class="section">${MODULES.map((m,i)=>{let ls=LESSONS.filter(l=>l.module===i),d=ls.filter(l=>S.completed[l.id]).length,available=ls.some(unlocked);return `<details class="card module" ${available?'open':''}><summary><div class="daynum">${m.icon}</div><div><h3>${i+1}. ${m.title}</h3><div class="muted small">${m.desc} · ${d}/${ls.length}</div></div></summary><div class="bar"><i style="width:${d/ls.length*100}%"></i></div>${ls.map(l=>`<div class="lessonrow"><div><strong>${esc(l.title)}</strong><span class="muted small">${SKILLS[l.skill]} · ${S.minutes} min</span></div>${unlocked(l)?btn(S.completed[l.id]?'Revisar':'Abrir',`openLesson('${l.id}')`,'secondary small'):'<span class="tag lock">Bloqueada</span>'}</div>`).join('')}</details>`}).join('')}</div>`}
const STEPS=['Teoria','Visualizar','Escutar','Compreender','Praticar','Avaliar'];
function openLesson(id){tunerTarget='auto';guided=null;let l=LESSONS.find(l=>l.id===id);if(!l||!unlocked(l)){toast('Conclua a aula anterior primeiro.');return;}stopSequence();stopMic();stopMetronome();current=l;step=0;quiz={options:shuffle(l.options),answer:null,passed:false};practiceChecks=[false,false,false];selfRating=0;lessonStart=Date.now();page='lesson';render();window.scrollTo(0,0)}
function gotoStep(n){if(n>step+1||n<0||n>5)return;if(n>3&&!quiz.passed){toast('Responda corretamente antes de avançar.');return}if(n===5&&!practiceChecks.every(Boolean)){toast('Confirme as etapas da prática primeiro.');return}stopSequence();stopMic();stopMetronome();step=n;render();window.scrollTo(0,0)}
function anatomy(){return `<svg class="diagram" viewBox="0 0 360 330" role="img" aria-label="Diagrama do violino"><g stroke="#513b30" stroke-width="2"><path d="M170 12q10-9 20 0v26l-5 36h-10l-5-36Z" fill="#9c623d"/><path d="M176 41h8l8 128h-24Z" fill="#383331"/><path d="M169 100c-42-19-65 5-55 33 5 13 20 12 20 33 0 18-42 27-38 66 4 36 43 68 84 68s80-32 84-68c4-39-38-48-38-66 0-21 15-20 20-33 10-28-13-52-55-33" fill="#b9824c"/><path d="M176 41h8l8 128h-24Z" fill="#383331"/><path d="M161 183h38l-7 9h-24Z" fill="#e3ba7d"/><path d="m172 198 16 0 11 66h-38Z" fill="#383331"/><path d="M140 169q-14 8-7 25m87-25q14 8 7 25" fill="none"/><path d="M167 25h27m-24 13h22M175 27v228m3-228v228m4-228v228m4-228v228" stroke="#f0dfa9" stroke-width="1.2"/></g><g fill="currentColor" font-size="11"><path d="M99 21h67M193 43h65M99 79h73M195 120h70M99 187h60M199 235h60M99 280h60" stroke="currentColor" stroke-dasharray="2 3"/><text x="95" y="24" text-anchor="end">Voluta</text><text x="262" y="46">Cravelhas</text><text x="95" y="82" text-anchor="end">Pestana</text><text x="268" y="124">Espelho</text><text x="95" y="190" text-anchor="end">Cavalete</text><text x="263" y="238">Estandarte</text><text x="95" y="283" text-anchor="end">Corpo</text></g></svg>`}
function bowDiagram(){return `<svg class="diagram" viewBox="0 0 360 180" role="img" aria-label="Arco: talão, crina, vareta e ponta"><path d="M25 68Q175 92 334 51" stroke="#95663f" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M34 105L332 58" stroke="#b9a98d" stroke-width="4"/><path d="M19 73h55l-9 29H34Z" fill="#4c3938"/><g fill="currentColor" font-size="12"><text x="20" y="32">Talão</text><text x="174" y="36" text-anchor="middle">Vareta</text><text x="180" y="134" text-anchor="middle">Crina</text><text x="303" y="29">Ponta</text><text x="34" y="155">← para cima</text><text x="228" y="155">para baixo →</text></g></svg><div class="callout">Arco para baixo: do talão em direção à ponta. Arco para cima: da ponta em direção ao talão. As ilustrações não substituem observação presencial da empunhadura.</div>`}
function postureDiagram(){return `<svg class="diagram" viewBox="0 0 320 230"><g stroke="currentColor" stroke-width="5" stroke-linecap="round" fill="none"><circle cx="135" cy="42" r="23"/><path d="M135 66v75l-31 72m31-72 31 72M106 82h58m-58 0-32 52 50 3m40-55 36 25 17-40"/></g><path d="M122 68 245 44 253 51 129 84Z" fill="#b78351"/><path d="m209 47 7 26" stroke="#d8b47b" stroke-width="3"/><g fill="currentColor" font-size="11"><text x="204" y="21">Braço livre</text><text x="9" y="63">Ombros baixos</text><text x="186" y="180">Coluna neutra</text></g></svg><div class="callout">Use um espelho para verificar ombros e alinhamento. Se sentir dor, pare. Peça a um professor para ajustar espaleira, queixeira e sustentação.</div>`}
function fingerboard(s=expString,o=expOffset){let x=i=>95+i*52, y=k=>55+ (1-2**(-k/12))*560;return `<svg class="diagram" viewBox="0 0 350 310" role="img" aria-label="Espelho do violino com posição do dedo"><path d="M72 49H278L297 292H53Z" fill="#332f2f" stroke="#654b3d" stroke-width="3"/><path d="M72 50H278" stroke="#e1cba7" stroke-width="8"/>${OPEN.map((n,i)=>`<text x="${x(i)}" y="29" fill="currentColor" text-anchor="middle" font-weight="700" font-size="14">${name(n)}</text><line x1="${x(i)}" y1="54" x2="${x(i)}" y2="292" stroke="${i===s?'#e4bd79':'#d2c9c1'}" stroke-width="${4-i*.7}"/>`).join('')}${POS.slice(1).map(p=>`<line x1="76" x2="274" y1="${y(p.o)}" y2="${y(p.o)}" stroke="#aaa" stroke-dasharray="3 6" opacity=".36"/><text x="61" y="${y(p.o)+4}" fill="#bfb2a5" text-anchor="end" font-size="10">${p.o}</text>`).join('')}<circle cx="${x(s)}" cy="${y(o)}" r="13" fill="#f1d099" stroke="#582638" stroke-width="2"/><text x="${x(s)}" y="${y(o)+4}" text-anchor="middle" font-weight="bold" fill="#402130" font-size="13">${POS[o].f}</text><text x="174" y="305" text-anchor="middle" fill="currentColor" font-size="11">↓ direção do cavalete · distância em semitons</text></svg>`}
const pitchMap=[0,0,1,2,2,3,3,4,4,5,6,6];
function staff(notes,beats=[],opts={}){if(!notes.length)return '';let count=Math.min(notes.length,16), w=Math.max(300,92+count*35),base=91, dy=5.5;return `<svg class="music" viewBox="0 0 ${w} 137" role="img" aria-label="Partitura ${notes.slice(0,count).map(full).join(', ')}"><g stroke="currentColor" stroke-width="1" opacity=".75">${[0,2,4,6,8].map(k=>`<line x1="8" x2="${w-8}" y1="${base-k*dy}" y2="${base-k*dy}"/>`).join('')}</g><text x="14" y="85" font-family="Georgia,serif" font-size="59" fill="currentColor">𝄞</text>${notes.slice(0,count).map((n,i)=>{let oct=Math.floor(n/12)-1, di=oct*7+pitchMap[n%12]-30, y=base-di*dy,x=74+i*35, b=beats[i]||1, stem=di>=4?-1:1, acc=LETTERS[n%12].includes('#')?'♯':LETTERS[n%12].includes('b')?'♭':'',ls=[];if(di<0)for(let k=-2;k>=di;k-=2)ls.push(k);if(di>8)for(let k=10;k<=di;k+=2)ls.push(k);return `${ls.map(k=>`<line x1="${x-10}" x2="${x+10}" y1="${base-k*dy}" y2="${base-k*dy}" stroke="currentColor"/>`).join('')}${acc?`<text x="${x-17}" y="${y+4}" font-size="14" fill="currentColor">${acc}</text>`:''}<ellipse cx="${x}" cy="${y}" rx="6.3" ry="4.2" transform="rotate(-15 ${x} ${y})" fill="${b>=2?'var(--bg)':'currentColor'}" stroke="currentColor" stroke-width="1.5"/>${b<4?`<line x1="${x+stem*5.5}" x2="${x+stem*5.5}" y1="${y}" y2="${y-stem*28}" stroke="currentColor" stroke-width="1.5"/>`:''}${b===.5?`<path d="M${x+stem*5.5} ${y-stem*28}q 10 5 6 15" stroke="currentColor" fill="none"/>`:''}${b===1.5?`<circle cx="${x+11}" cy="${y}" r="1.9" fill="currentColor"/>`:''}${opts.names?`<text x="${x}" y="124" font-size="10" text-anchor="middle" fill="currentColor">${name(n)}</text>`:''}`}).join('')}</svg>`}
function stringsVisual(){return `<div class="note-grid">${OPEN.map((n,i)=>`<button class="btn secondary" onclick="playOne(${n})">${name(n)} · ${full(n)}<br>♪</button>`).join('')}</div>${staff(OPEN,[],{names:true})}<p class="muted small center">Da corda mais grave (Sol) à mais aguda (Mi).</p>`}
function visual(l){switch(l.visual){case'anatomy':return anatomy();case'bow':return bowDiagram();case'posture':return postureDiagram();case'strings':return stringsVisual();case'finger':{let f=l.notes.flatMap(fingers).find(f=>f.f!=='0')||{string:1,o:2,note:64};return `${fingerboard(f.string,f.o)}<p class="center">${full(f.note)} · ${f.t} · corda ${name(OPEN[f.string])}</p>${staff(l.notes.slice(0,12),[],{names:true})}${btn('Abrir explorador após a aula','go(\'tools\');setTool(\'explorer\')','secondary')}`};case'rhythm':return `<div class="grid">${[['𝅝','Semibreve','4 tempos'],['𝅗𝅥','Mínima','2 tempos'],['♩','Semínima','1 tempo'],['♪','Colcheia','½ tempo']].map(([a,b,c])=>`<div class="card center"><div class="big-note">${a}</div><strong>${b}</strong><p class="muted">${c}</p></div>`).join('')}</div>`;default:return staff(l.notes.slice(0,16),[],{names:true})||anatomy()}}
function lessonPage(){let l=current;if(!l)return homePage();let body='';if(step===0)body=`<div class="eyebrow">Conhecimento antes da prática</div><h2>${esc(l.title)}</h2><div class="prose"><p>${esc(l.theory)}</p></div><div class="callout"><strong>Objetivo da aula</strong><p>${esc(l.practice)}</p></div>`;if(step===1)body=`<h2>Veja como funciona</h2>${visual(l)}`;if(step===2)body=`<h2>Escute e observe</h2><p>${l.notes.length?'Ouça primeiro. Observe o contorno, a duração ou a nota que está sendo estudada. O som é uma referência sintetizada, não uma gravação real de violino.':'Esta lição é de preparação física. Observe a demonstração visual e descreva o procedimento antes da prática.'}</p>${l.notes.length?`${staff(l.notes.slice(0,16),[],{names:true})}<div class="actions">${btn('▶ Ouvir demonstração',`playSequence(current.notes,[],60)`)}${btn('Parar','stopSequence()','secondary')}</div>`:visual(l)}<div class="callout">${l.notes.length?'Se não ouvir, verifique o volume e o modo silencioso, depois toque no botão novamente.':'Não há uma sequência sonora obrigatória nesta aula.'}</div>`;if(step===3)body=`<h2>Teste de compreensão</h2><p>${esc(l.question)}</p><div class="choices">${quiz.options.map((o,i)=>`<button class="choice ${quiz.answer===o?(o===l.answer?'correct':'wrong'):''}" onclick="answerLesson(${i})" ${quiz.passed?'disabled':''}>${esc(o)}</button>`).join('')}</div>${quiz.answer?`<div class="feedback ${quiz.passed?'ok':'bad'}">${quiz.passed?'Correto!':'Tente novamente.'} ${esc(l.feedback)}</div>`:''}`;if(step===4)body=`<h2>Prática no instrumento</h2><p>${esc(l.practice)}</p>${l.notes.length?staff(l.notes.slice(0,16),[],{names:true}):visual(l)}<div class="actions">${l.notes.length?btn('▶ Referência lenta','playSequence(current.notes,[],55)','secondary'):''}${btn('♪ Metrônomo 60 BPM','toggleMetronome()','secondary')}</div><div id="met-mini" class="muted small"></div>${['Preparei o instrumento e compreendi a atividade.','Executei a atividade no meu ritmo e respeitei os limites do corpo.','Observei onde acertei e o que precisa melhorar.'].map((t,i)=>`<label class="check"><input type="checkbox" ${practiceChecks[i]?'checked':''} onchange="checkPractice(${i},this.checked)">${t}</label>`).join('')}<p class="muted small">A confirmação é uma autoavaliação, não uma validação automática da postura.</p>${l.notes.length&&l.skill!=='ritmo'?`<div class="line"></div><h3>Compare com o afinador</h3>${tunerPanel(true)}`:''}`;if(step===5)body=`<h2>Como foi a prática?</h2><p>A autoavaliação alimenta o plano. Não avance se a atividade física ainda estiver desconfortável.</p><div class="choices">${['Preciso de ajuda e revisão','Consegui com dificuldade','Consegui com alguma revisão','Consegui com segurança'].map((x,i)=>`<button class="choice ${selfRating===i+1?'selected':''}" onclick="rate(${i+1})">${i+1} · ${x}</button>`).join('')}</div><label for="note-journal">Anotação (opcional)</label><textarea id="note-journal" placeholder="O que foi mais difícil?"></textarea><div class="callout">Se precisar de revisão, a aula permanece disponível e o plano prioriza reforço.</div>`;return `<div class="lessonbody"><button class="btn ghost" onclick="go('course')">← Curso</button><div class="eyebrow">Módulo ${l.module+1} · ${SKILLS[l.skill]}</div><h1>${esc(l.title)}</h1><div class="steps">${STEPS.map((s,i)=>`<button class="step ${i===step?'current':i<step?'past':''}" onclick="gotoStep(${i})" ${i>step?'disabled':''}>${i+1}. ${s}</button>`).join('')}</div><div class="card">${body}</div><div class="lesson-nav">${step>0?btn('← Voltar',`gotoStep(${step-1})`,'secondary'):'<span></span>'}${step<5?btn('Continuar →',`gotoStep(${step+1})`):btn('Concluir aula','finishLesson()')}</div></div>`}
function answerLesson(i){if(quiz.passed)return;quiz.answer=quiz.options[i];quiz.passed=quiz.answer===current.answer;record(current.skill,quiz.passed,current.question,'lesson');render()}
function checkPractice(i,v){practiceChecks[i]=v}function rate(n){let text=$('#note-journal')?.value||'';selfRating=n;render();$('#note-journal').value=text}
function finishLesson(){if(!selfRating){toast('Selecione sua autoavaliação.');return}let first=!S.completed[current.id], note=$('#note-journal')?.value?.trim()||'', mins=Math.max(1,Math.round((Date.now()-lessonStart)/60000));record(current.skill,selfRating>=3,'Prática: '+current.title,'practice');if(selfRating>=3){S.completed[current.id]={t:Date.now(),rating:selfRating};S.xp+=first?25:4}else S.xp+=2;S.sessions.push({title:current.title,t:Date.now(),minutes:mins,completed:selfRating>=3});if(note)S.journal.push({t:Date.now(),title:current.title,note});save();go('home');toast(selfRating>=3?'Aula concluída! Plano atualizado.':'Prática registrada. Vamos revisar esta aula.')}
// Audio: unlocked by an explicit tap; synthesized reference tone, no network calls.
async function audio(){if(!audioCtx){let AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Áudio indisponível');audioCtx=new AC()}if(audioCtx.state!=='running')await audioCtx.resume();return audioCtx}
function sound(f,d=.65,when=null,vol=.18,type='violin'){if(!audioCtx)return;let t=when??audioCtx.currentTime, g=audioCtx.createGain();g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(vol,t+.035);g.gain.setValueAtTime(vol*.75,t+Math.max(.06,d-.08));g.gain.exponentialRampToValueAtTime(.001,t+d+.03);g.connect(audioCtx.destination);let harmonics=type==='click'?[1]:[1,.28,.14,.075];harmonics.forEach((a,i)=>{let o=audioCtx.createOscillator(),v=audioCtx.createGain();o.type='sine';o.frequency.value=f*(i+1);v.gain.value=a;o.connect(v);v.connect(g);audioNodes.add(o);o.onended=()=>{audioNodes.delete(o);o.disconnect();v.disconnect()};o.start(t);o.stop(t+d+.06)})}
async function playOne(n){try{await audio();sound(hz(n),.8)}catch(e){toast('Não foi possível iniciar o áudio.')}}
function stopSequence(){seqToken++;playing=false;for(let o of audioNodes){try{o.stop()}catch{}}audioNodes.clear()}
async function playSequence(ns,beats=[],speed=60){stopSequence();let token=seqToken;try{await audio();if(token!==seqToken)return;playing=true;let time=audioCtx.currentTime+.05,unit=60/speed;ns.forEach((n,i)=>{let b=beats[i]||1;sound(hz(n),unit*b*.87,time,.16);time+=unit*b});setTimeout(()=>{if(token===seqToken)playing=false},Math.max(0,(time-audioCtx.currentTime)*1000))}catch{toast('Áudio indisponível. Verifique o volume e toque novamente.')}}
function stopMetronome(){clearInterval(metTimer);metTimer=null;metBeat=0;let p=$('#pulse');if(p){p.classList.remove('on');p.textContent='—'}let m=$('#met-mini');if(m)m.textContent=''}
async function toggleMetronome(){if(metTimer){stopMetronome();return}try{await audio();const tick=()=>{let b=metBeat%meter+1;sound(b===1?1300:850,.07,null,.12,'click');metBeat++;let p=$('#pulse');if(p){p.textContent=b;p.classList.add('on');setTimeout(()=>p?.classList.remove('on'),110)}let m=$('#met-mini');if(m)m.textContent=`Pulso ${b}/${meter} · ${bpm} BPM`};tick();metTimer=setInterval(tick,60000/bpm)}catch{toast('Não foi possível iniciar o metrônomo.')}}
// Microphone / autocorrelation: YIN-style difference, normalized, interpolated.
function detectPitch(buffer,sr){let n=buffer.length, rms=Math.sqrt(buffer.reduce((a,v)=>a+v*v,0)/n);if(rms<.008)return null;let max=Math.min(Math.floor(sr/160),n>>1),min=Math.floor(sr/1600),d=new Float32Array(max+1);let running=0;d[0]=1;for(let tau=1;tau<=max;tau++){let sum=0;for(let j=0;j<n-max;j++){let v=buffer[j]-buffer[j+tau];sum+=v*v}running+=sum;d[tau]=running?sum*tau/running:1}let tau=-1;for(let k=min;k<max;k++)if(d[k]<.15){while(k+1<max&&d[k+1]<d[k])k++;tau=k;break}if(tau<0)return null;let a=d[tau-1],b=d[tau],c=d[tau+1],den=2*(2*b-a-c),delta=den?(c-a)/den:0;let f=sr/(tau+clamp(delta,-.5,.5));return {f,confidence:1-b}}
async function startMic(mode='free'){if(mic){stopMic();return}if(!navigator.mediaDevices?.getUserMedia){toast('O microfone exige HTTPS ou localhost.');return}try{await audio();mic=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});analyser=audioCtx.createAnalyser();analyser.fftSize=2048;audioCtx.createMediaStreamSource(mic).connect(analyser);tuneSamples=[];tunerMode=mode;updateTunerUI();let buff=new Float32Array(analyser.fftSize),last=0;const loop=t=>{if(!mic)return;pitchFrame=requestAnimationFrame(loop);if(t-last<100)return;last=t;analyser.getFloatTimeDomainData(buff);let r=detectPitch(buff,audioCtx.sampleRate);if(!r)return;let f=r.f, n=Math.round(69+12*Math.log2(f/S.reference)),target=tunerTarget==='auto'?n:Number(tunerTarget),c=1200*Math.log2(f/hz(target));tuneSamples.push({n,target,c,t:Date.now()});if(tuneSamples.length>600)tuneSamples.shift();if(guided)guidedSample(f);let el=$('#pitch-note');if(el){el.textContent=full(n);$('#pitch-hz').textContent=`${f.toFixed(1)} Hz · alvo ${full(target)} (${hz(target).toFixed(1)} Hz)`;$('#pitch-cents').textContent=`${c>=0?'+':''}${Math.round(c)} cents`;$('#pitch-advice').textContent=Math.abs(c)<=10?'Dentro da faixa de referência.':tunerTarget==='auto'?'Compare com a nota de referência.':c<0?'Abaixo do alvo (grave).':'Acima do alvo (aguda).';$('#needle').style.left=`${50+clamp(c,-50,50)}%`;$('#pitch-cents').style.color=Math.abs(c)<=10?'var(--green)':'var(--gold)';$('#sample-count').textContent=tuneSamples.length+' leituras válidas'}};pitchFrame=requestAnimationFrame(loop)}catch(e){stopMic();toast('Microfone indisponível. Verifique a permissão do navegador.')}}
function stopMic(){if(mic)mic.getTracks().forEach(t=>t.stop());mic=null;analyser=null;cancelAnimationFrame(pitchFrame);updateTunerUI()}
function updateTunerUI(){let b=$('#mic-btn');if(b)b.textContent=mic?'■ Desligar microfone':'🎙 Ativar microfone'}
function tunerPanel(inLesson=false){let choices=inLesson?[...new Set(current.notes)]:[...new Set([...OPEN,...OPEN.flatMap(n=>POS.map(p=>n+p))])].sort((a,b)=>a-b);return `<div class="center"><div class="big-note" id="pitch-note">—</div><p class="muted" id="pitch-hz">Toque uma nota isolada em ambiente silencioso</p><div class="gauge"><i id="needle" class="needle"></i></div><div class="gauge-label"><span>−50¢ · grave</span><span>0 · afinado</span><span>+50¢ · agudo</span></div><h3 id="pitch-cents">— cents</h3><p id="pitch-advice" class="muted">A frequência é uma estimativa.</p><div class="control"><label for="tune-target">Nota-alvo</label><select id="tune-target" onchange="tunerTarget=this.value;tuneSamples=[]"><option value="auto">Automática</option>${choices.map(n=>`<option value="${n}" ${String(n)===String(tunerTarget)?'selected':''}>${full(n)}</option>`).join('')}</select></div><div class="actions" style="justify-content:center"><button id="mic-btn" class="btn" onclick="startMic('${inLesson?'lesson':'free'}')">🎙 Ativar microfone</button>${btn('Ouvir alvo','playOne(tunerTarget===\'auto\'?69:Number(tunerTarget))','secondary')}${btn('Avaliar amostra','assessTuning()','secondary')}</div><p id="sample-count" class="muted small">0 leituras válidas</p><div id="tune-result"></div></div><p class="muted small">Use uma nota-alvo para avaliar afinação. Afinar cordas soltas exige ajuste com orientação; não aumente a tensão excessivamente. Microfone não avalia postura nem qualidade do arco.</p>`}
function assessTuning(){if(tunerTarget==='auto'){toast('Escolha uma nota-alvo.');return}let a=tuneSamples.filter(x=>x.target===Number(tunerTarget)).slice(-80);if(a.length<8){toast('Toque a nota por alguns segundos.');return}let good=a.filter(x=>Math.abs(x.c)<=20).length, p=Math.round(good/a.length*100), avg=Math.round(a.reduce((s,x)=>s+x.c,0)/a.length);record('afinacao',p>=70,`${full(Number(tunerTarget))}: ${p}% dentro de ±20¢`);$('#tune-result').innerHTML=`<div class="feedback ${p>=70?'ok':'bad'}">${p}% das leituras dentro de ±20 cents · desvio médio ${avg}¢. ${p>=70?'Boa estabilidade nesta amostra.':'Repita lentamente, sem tensão.'}</div>`;toast('Amostra registrada na evolução.')}
// Explorador de cordas, escalas, metrônomo, gravação, afinador.
const TOOLS=[['tuner','Afinador'],['explorer','Mapa de notas'],['metronome','Metrônomo'],['scales','Escalas'],['record','Gravador']];let scaleKey=62,scaleMode='major', recordings=[];
function setTool(t){stopSequence();stopMic();guided=null;stopMetronome();if(recRecording)stopRecording();tool=t;tunerTarget='auto';if(page!=='tools')page='tools';render();window.scrollTo(0,0)}
function toolsPage(){let b='';if(tool==='tuner')b=`<div class="card"><h2>Afinador cromático</h2><p class="muted">Referência: Lá = ${S.reference} Hz. Selecione uma corda ou nota-alvo.</p>${tunerPanel()}<div class="line"></div>${stringsVisual()}<div class="control"><label>Referência de Lá (Hz)</label><input type="number" min="415" max="466" value="${S.reference}" onchange="S.reference=clamp(Number(this.value)||440,415,466);save();render()"></div></div>`;if(tool==='explorer'){let n=OPEN[expString]+expOffset,p=POS[expOffset];b=`<div class="grid"><div class="card"><h2>Explorador de dedilhado</h2><div class="big-note">${full(n)}</div><p>${p.t} · corda ${name(OPEN[expString])} · ${hz(n).toFixed(1)} Hz</p>${fingerboard()}<div class="note-grid">${OPEN.map((x,i)=>`<button class="btn secondary ${expString===i?'active':''}" onclick="expString=${i};render()">${name(x)}</button>`).join('')}</div><div class="line"></div><label>Posição do dedo</label><select class="wide" onchange="expOffset=Number(this.value);render()">${POS.map(p=>`<option value="${p.o}" ${p.o===expOffset?'selected':''}>${p.t} — ${full(OPEN[expString]+p.o)}</option>`).join('')}</select><div class="actions">${btn('▶ Ouvir nota',`playOne(${n})`)}</div><p class="muted small">O mapa é esquemático. As posições seguem distâncias relativas temperadas; a afinação real depende da corda e do contexto. Não use o desenho para medir o seu instrumento.</p></div><div class="card"><h2>Na partitura</h2>${staff([n],[],{names:true})}<h3>Outras possibilidades</h3>${fingers(n).map(p=>`<p>${name(OPEN[p.string])} · ${p.t}</p>`).join('')}<div class="callout">O dedo 1 é o indicador. O 2 é o médio. O 3 é o anelar. O 4 é o mínimo. O 0 indica corda solta.</div><h3>Todas as notas da corda ${name(OPEN[expString])}</h3>${POS.map(p=>`<div class="lessonrow"><span>${p.t}</span><button class="btn small secondary" onclick="expOffset=${p.o};render();playOne(${OPEN[expString]+p.o})">${full(OPEN[expString]+p.o)} ♪</button></div>`).join('')}</div></div>`}if(tool==='metronome')b=`<div class="card center"><h2>Metrônomo</h2><div class="big-note" id="bpm-value">${bpm} BPM</div><input aria-label="BPM" type="range" min="35" max="200" value="${bpm}" oninput="changeBpm(this.value)"><div class="control"><label>Tempos por compasso</label><select onchange="meter=Number(this.value);metBeat=0">${[2,3,4,6].map(n=>`<option ${meter===n?'selected':''}>${n}</option>`).join('')}</select></div><div id="pulse" class="pulse">—</div>${btn('▶ Iniciar / parar','toggleMetronome()')}</div>`;if(tool==='scales'){let ns=scaleNotes();b=`<div class="card"><h2>Escalas e arpejos</h2><p>Explore o padrão de intervalos, as notas, a partitura e as possibilidades de dedilhado na primeira posição.</p><div class="control"><label>Tonalidade</label><select onchange="scaleKey=Number(this.value);render()">${[55,57,60,62,64,65,67,69,70,71].map(n=>`<option value="${n}" ${scaleKey===n?'selected':''}>${full(n)}</option>`).join('')}</select><select onchange="scaleMode=this.value;render()">${[['major','Maior'],['minor','Menor natural'],['arp','Arpejo maior'],['arpmin','Arpejo menor']].map(([v,t])=>`<option value="${v}" ${scaleMode===v?'selected':''}>${t}</option>`).join('')}</select></div>${staff(ns,[],{names:true})}<div class="actions">${btn('▶ Ouvir a 60 BPM','playSequence(scaleNotes(),[],60)')}${btn('Parar','stopSequence()','secondary')}</div><div class="line"></div>${ns.map(n=>`<div class="lessonrow"><strong>${full(n)}</strong><span class="muted small">${fingers(n).map(f=>`${name(OPEN[f.string])}: ${f.t}`).join(' / ')||'Fora do mapa inicial'}</span></div>`).join('')}</div>`};if(tool==='record')b=`<div class="card"><h2>Diário sonoro</h2><p>Grave um trecho, ouça e compare suas execuções. O áudio não é enviado a nenhum servidor; baixe os arquivos para conservar suas gravações.</p><div class="actions">${btn(recRecording?'■ Encerrar gravação':'● Gravar','toggleRecording()')}${recUrl?`<a class="btn secondary" download="archet-gravacao.${recorder?.mimeType?.includes('mp4')?'m4a':'webm'}" href="${recUrl}">Salvar áudio</a>`:''}</div>${recUrl?`<audio controls src="${recUrl}"></audio>`:''}<div class="line"></div><p class="muted small">As gravações desta sessão ficam disponíveis até fechar/recarregar a página. Para comparar ao longo dos dias, salve os arquivos no dispositivo.</p></div>`;return `<h1>Ferramentas do estúdio</h1><div class="tabs">${TOOLS.map(([t,a])=>btn(a,`setTool('${t}')`,'secondary '+(tool===t?'active':''))).join('')}</div>${b}`}
function changeBpm(v){bpm=Number(v);$('#bpm-value').textContent=bpm+' BPM';if(metTimer){stopMetronome();toggleMetronome()}}
function scaleNotes(){let intervals={major:[0,2,4,5,7,9,11,12],minor:[0,2,3,5,7,8,10,12],arp:[0,4,7,12],arpmin:[0,3,7,12]};return intervals[scaleMode].map(i=>scaleKey+i)}
async function toggleRecording(){if(recRecording){stopRecording();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Gravador não disponível neste navegador.');return}try{recStream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(recStream);recChunks=[];recorder.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data)};recorder.onstop=()=>{if(recUrl)URL.revokeObjectURL(recUrl);recUrl=URL.createObjectURL(new Blob(recChunks,{type:recorder.mimeType||'audio/webm'}));recStream?.getTracks().forEach(t=>t.stop());recStream=null;recRecording=false;if(page==='tools'&&tool==='record')render();toast('Gravação pronta para ouvir.')};recorder.start();recRecording=true;render()}catch{toast('Não foi possível gravar. Verifique as permissões.')}}
function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();recRecording=false}
const LABS=[['reading','𝄞','Leitura','Reconheça notas no pentagrama.','leitura'],['ear','◉','Ouvido','Compare alturas e intervalos.','ouvido'],['rhythm','♩','Ritmo','Ouça e reproduza padrões.','ritmo'],['finger','♬','Dedilhado','Associe notas, cordas e dedos.','dedilhado'],['tuning','◎','Afinação','Compare seu som à referência.','afinacao'],['pieces','♫','Repertório','Estude melodias em trechos.','repertorio']];
let guided=null;
let labMode='beginner', rhythmPattern=[1,1,2,1], labAnswer=null, earHeard=false, rhythmHeard=false, rhythmTaps=[], rhythmStart=0, rhythmTimer=null;
function setLab(l){stopSequence();stopMic();guided=null;clearTimeout(rhythmTimer);lab=l;labQ=null;labAnswer=null;labEnabled=false;earHeard=false;rhythmHeard=false;rhythmTaps=[];rhythmRun=null;if(l==='tuning')tunerTarget='auto';render()}
function labsPage(){let obj=LABS.find(a=>a[0]===lab),content='';if(!labEnabled&&lab!=='tuning'&&lab!=='pieces')content=`<div class="card"><div class="eyebrow">Aprenda antes de exercitar</div><h2>${obj[2]} · preparação</h2><p>${({reading:'Na clave de Sol, a segunda linha é Sol4. As linhas, de baixo para cima, são Mi, Sol, Si, Ré e Fá; os espaços são Fá, Lá, Dó e Mi. Comece pelas quatro cordas abertas.',ear:'Compare a segunda altura com a primeira: subir significa mais agudo; descer, mais grave. No modo intervalos, semitom = 1, tom = 2, terça menor = 3, terça maior = 4, quarta = 5, quinta = 7 e oitava = 12 semitons.',rhythm:'Pulso é regular. Uma semínima vale um pulso; duas colcheias ocupam um pulso; a mínima dura dois. Escute o padrão e reproduza os ataques após a contagem inicial.',finger:'Corda solta = dedo 0. Indicador = 1, médio = 2, anelar = 3, mínimo = 4. No padrão maior inicial, as distâncias da corda solta são 0, 2, 4, 5 e 7 semitons. Posições baixas alteram a distância.'})[lab]}</p>${lab==='reading'?stringsVisual():lab==='finger'?fingerboard():lab==='ear'?`<div class="actions">${btn('Ouvir sobe','playSequence([62,69],[],90)','secondary')}${btn('Ouvir desce','playSequence([69,62],[],90)','secondary')}</div>`:''}<div class="control"><label>Modo</label><select onchange="labMode=this.value"><option value="beginner" ${labMode==='beginner'?'selected':''}>Fundamentos</option><option value="advanced" ${labMode==='advanced'?'selected':''}>Desafio</option></select></div><div class="actions">${btn('Entendi · iniciar','startLab()')}</div></div>`;else if(lab==='tuning')content=`<div class="card"><h2>Prática de afinação</h2><p>Afine primeiro as cordas, depois escolha uma nota-alvo. Sustente a nota sem tentar compensar a cada oscilação. Registre a amostra para medir progresso.</p>${tunerPanel()}</div>`;else if(lab==='pieces')content=piecePanel();else if(lab==='rhythm')content=rhythmPanel();else content=questionPanel();return `<h1>Laboratórios</h1><p class="muted">Treine uma habilidade específica, com explicação antes de cada rodada. Os resultados alimentam seu plano.</p><div class="grid three section">${LABS.map(([id,i,t,d])=>`<button class="card" style="text-align:left;color:var(--ink);${id===lab?'border-color:var(--wine);background:var(--soft)':''}" onclick="setLab('${id}')"><span class="metric">${i}</span><h3>${t}</h3><span class="muted small">${d}</span></button>`).join('')}</div><div class="section">${content}</div>`}
function startLab(){labEnabled=true;newQuestion()}
function newQuestion(){labAnswer=null;earHeard=false;rhythmHeard=false;rhythmRun=null;rhythmTaps=[];if(lab==='rhythm'){rhythmPattern=labMode==='advanced'?pick([[.5,.5,1,2],[1.5,.5,1,1],[1,.5,.5,2]]):pick([[1,1,1,1],[2,1,1],[1,1,2],[1,2,1]]);render();return}if(lab==='reading'){let n=pick(labMode==='advanced'?[55,57,59,60,62,64,65,66,67,69,71,72,73,74,76,77,78,79,81]:OPEN);let ans=full(n);labQ={n,prompt:'Qual nota está escrita?',correct:ans,opts:shuffle([ans,...shuffle([...new Set([...OPEN,...Array.from({length:19},(_,i)=>55+i)].map(full))].filter(x=>x!==ans)).slice(0,3)]),detail:`Leitura de ${full(n)}`,explain:`A nota escrita é ${full(n)}. ${fingers(n).map(p=>name(OPEN[p.string])+' '+p.t).join(' / ')}`}}else if(lab==='finger'){let s=pick([0,1,2,3]),o=pick(labMode==='advanced'?[0,1,2,3,4,5,6,7,8]:[0,2,4,5,7]),n=OPEN[s]+o;let ans=full(n);labQ={s,o,n,prompt:`Qual nota soa na corda ${name(OPEN[s])}, ${POS[o].t.toLowerCase()}?`,correct:ans,opts:shuffle([ans,...shuffle(POS.map(p=>full(OPEN[s]+p.o)).filter(a=>a!==ans)).slice(0,3)]),detail:`${name(OPEN[s])}: ${POS[o].t}`,explain:`${POS[o].t} fica ${o} semitom(ns) acima da corda, produzindo ${ans}.`}}else if(lab==='ear'){let n=pick([62,64,65,67,69,71]),i=pick(labMode==='advanced'?[1,2,3,4,5,7,12]:[-5,-3,-2,0,2,3,5]);let intervals={1:'Segunda menor',2:'Segunda maior',3:'Terça menor',4:'Terça maior',5:'Quarta justa',7:'Quinta justa',12:'Oitava'},a=labMode==='advanced'?intervals[i]:i===0?'Mesma altura':i>0?'Mais aguda':'Mais grave';labQ={n,notes:[n,n+i],prompt:labMode==='advanced'?'Qual intervalo você ouviu?':'Como a segunda nota se compara à primeira?',correct:a,opts:labMode==='advanced'?shuffle([a,...shuffle(Object.values(intervals).filter(x=>x!==a)).slice(0,3)]):['Mais grave','Mesma altura','Mais aguda'],detail:`Ouvido: ${a}`,explain:`${full(n)} → ${full(n+i)}. ${a}.`}}render()}
function questionPanel(){if(!labQ)return `<div class="card">${btn('Nova questão','newQuestion()')}</div>`;let q=labQ;return `<div class="card"><div class="eyebrow">${labMode==='advanced'?'Desafio':'Fundamentos'}</div><h2>${esc(q.prompt)}</h2>${lab==='reading'?staff([q.n]):lab==='finger'?fingerboard(q.s,q.o):`<div class="actions">${btn('▶ Ouvir as duas notas','hearLab()')}</div><p class="muted small">Ouça antes de responder. No modo Fundamentos, não é necessário adivinhar o nome das notas.</p>`}<div class="choices">${q.opts.map((v,i)=>`<button class="choice ${labAnswer===v?(v===q.correct?'correct':'wrong'):''}" onclick="answerLab(${i})" ${labAnswer!==null?'disabled':''}>${esc(v)}</button>`).join('')}</div>${labAnswer!==null?`<div class="feedback ${labAnswer===q.correct?'ok':'bad'}">${labAnswer===q.correct?'Correto!':'Resposta: '+esc(q.correct)+'.'} ${esc(q.explain)}</div>${btn('Próximo exercício','newQuestion()')}`:''}<div class="actions">${btn('Rever teoria','setLab(lab)','secondary small')}</div></div>`}
function hearLab(){earHeard=true;playSequence(labQ.notes,[],90)}function answerLab(i){if(lab==='ear'&&!earHeard){toast('Ouça as notas antes de responder.');return}if(labAnswer!==null)return;labAnswer=labQ.opts[i];record(LABS.find(x=>x[0]===lab)[4],labAnswer===labQ.correct,labQ.detail);render()}
function rhythmPanel(){return `<div class="card"><h2>Reproduza o ritmo</h2><p>Ouça o padrão. Depois pressione Iniciar tentativa. Quatro cliques de preparação serão seguidos pelo momento de começar; toque a área uma vez para cada ataque.</p><div class="grid four">${rhythmPattern.map(b=>`<div class="card center"><div class="metric">${b===2?'𝅗𝅥':b===.5?'♪':'♩'}</div><span class="muted small">${b} tempo(s)</span></div>`).join('')}</div><div class="actions">${btn('▶ Ouvir padrão','hearRhythm()')}${btn('Iniciar tentativa','beginRhythm()','secondary')}</div><div class="pulse" id="rhythm-count">—</div><button class="rhythm-tap" onclick="tapRhythm()">TOQUE AQUI</button><div id="rhythm-info" class="feedback">Aguardando · 0/${rhythmPattern.length} ataques</div><div class="actions">${btn('Novo padrão','newQuestion()','secondary small')}${btn('Rever teoria','setLab(lab)','secondary small')}</div></div>`}
function hearRhythm(){rhythmHeard=true;playSequence(rhythmPattern.map(()=>62),rhythmPattern,60)}
async function beginRhythm(){if(!rhythmHeard){toast('Escute o padrão uma vez.');return}stopSequence();clearTimeout(rhythmTimer);rhythmTaps=[];rhythmRun='count';try{await audio();let ctx=audioCtx,t=ctx.currentTime+.12;for(let i=0;i<4;i++)sound(850,.08,t+i,.13,'click');sound(1300,.08,t+4,.13,'click');rhythmStart=performance.now()+(t+4-ctx.currentTime)*1000;let n=0;const show=()=>{if(rhythmRun!=='count')return;let e=$('#rhythm-count');if(!e)return;if(n<4){e.textContent=++n;rhythmTimer=setTimeout(show,1000)}else{e.textContent='JÁ';rhythmRun='tap';$('#rhythm-info').textContent='Toque no pulso e siga as durações.';rhythmTimer=setTimeout(()=>finishRhythm(),Math.max(1,rhythmPattern.reduce((a,b)=>a+b,0))*1000+2500)}};show()}catch{toast('Áudio indisponível.')}}
function tapRhythm(){if(rhythmRun!=='tap')return;rhythmTaps.push(performance.now()-rhythmStart);$('#rhythm-info').textContent=`${rhythmTaps.length}/${rhythmPattern.length} ataques`;if(rhythmTaps.length>=rhythmPattern.length)finishRhythm()}
function finishRhythm(){clearTimeout(rhythmTimer);if(rhythmRun!=='tap')return;rhythmRun='done';let target=[],x=0;rhythmPattern.forEach(b=>{target.push(x);x+=b*1000});let n=rhythmTaps.length,errors=target.map((v,i)=>Math.abs((rhythmTaps[i]??(v+1000))-v)),avg=Math.round(errors.reduce((a,b)=>a+b,0)/errors.length),ok=n===target.length&&avg<=220;record('ritmo',ok,`Padrão ${rhythmPattern.join('–')}: ${avg} ms de desvio médio`);$('#rhythm-info').textContent=`${ok?'Bom ritmo!':'Repita mais lentamente.'} ${n}/${target.length} ataques · desvio médio estimado ${avg} ms.`;$('#rhythm-count').textContent=ok?'✓':'↻'}
let pieceSpeed=55,pieceShowNames=true;
function piecePanel(){let p=PIECES[pieceIndex],len=8,start=pieceSegment*len,ns=p.notes.slice(start,start+len),bs=p.beats.slice(start,start+len);return `<div class="card"><h2>Estúdio de repertório</h2><p class="muted">Melodias originais ou de domínio público em arranjos didáticos. Comece por um trecho pequeno.</p><select class="wide" onchange="stopGuided();pieceIndex=Number(this.value);pieceSegment=0;render()">${PIECES.map((p,i)=>`<option value="${i}" ${i===pieceIndex?'selected':''}>${p.title}</option>`).join('')}</select><h3>${p.title}</h3><p class="muted small">${p.source} · ${p.key}</p>${Object.keys(S.completed).length<p.min?`<div class="callout">Prévia livre: esta peça é recomendada após aproximadamente ${p.min} aulas. Estude as notas já conhecidas primeiro.</div>`:''}<div class="control"><label>Velocidade: <strong id="piece-speed">${pieceSpeed} BPM</strong></label><input type="range" min="35" max="120" value="${pieceSpeed}" oninput="pieceSpeed=Number(this.value);document.querySelector('#piece-speed').textContent=pieceSpeed+' BPM'"></div><label class="check"><input type="checkbox" ${pieceShowNames?'checked':''} onchange="pieceShowNames=this.checked;render()">Mostrar nomes das notas</label><div class="line"></div><div class="row"><strong>Trecho ${pieceSegment+1}/${Math.ceil(p.notes.length/len)}</strong></div>${staff(ns,bs,{names:pieceShowNames})}<div class="actions">${btn('▶ Ouvir trecho','playPiece(false)')}${btn('Ouvir peça inteira','playPiece(true)','secondary')}${btn('Parar','stopSequence()','secondary')}</div><div class="actions">${btn('← Trecho anterior','stopGuided();pieceSegment=Math.max(0,pieceSegment-1);render()','secondary small')}${btn('Próximo trecho →',`stopGuided();pieceSegment=Math.min(${Math.ceil(p.notes.length/len)-1},pieceSegment+1);render()`,'secondary small')}</div><div class="callout">Dedilhado sugerido: ${ns.map(n=>{let f=fingers(n)[0];return `${full(n)} (${f?name(OPEN[f.string])+': '+f.f:'—'})`}).join(' · ')}</div><div class="actions">${btn('Registrei uma prática','recordPiece()','good')}</div><div class="line"></div><h3>Prática guiada pelo microfone</h3><p class="muted small">Toque cada nota e sustente brevemente até o aplicativo reconhecer a altura; notas repetidas podem ser reconhecidas sem novo ataque. O modo não avalia o ritmo da melodia: use o metrônomo e a referência para isso.</p><div id="guided-status" class="callout">Pronto para iniciar.</div><div class="actions">${btn('Iniciar sequência','startGuided()')}${btn('Parar','stopGuided()','secondary')}</div></div>`}
async function startGuided(){stopSequence();stopMic();let p=PIECES[pieceIndex],a=pieceSegment*8;guided={notes:p.notes.slice(a,a+8),i:0,streak:0,wrong:0,waitUntil:0};let el=$('#guided-status');if(el)el.textContent='Toque e sustente '+full(guided.notes[0])+' · 1/'+guided.notes.length;await startMic('guided');if(!mic){guided=null;if(el)el.textContent='Microfone indisponível. Ative a permissão e tente novamente.'}}
function guidedSample(f){if(!guided||Date.now()<guided.waitUntil)return;let n=guided.notes[guided.i],c=1200*Math.log2(f/hz(n));if(Math.abs(c)<=30){guided.streak++;if(guided.streak>=4){guided.i++;guided.streak=0;guided.waitUntil=Date.now()+450;let el=$('#guided-status');if(guided.i>=guided.notes.length){let wrong=guided.wrong;guided=null;record('repertorio',true,'Sequência guiada concluída · '+wrong+' amostras fora do alvo');stopMic();if(el)el.textContent='Sequência concluída! Todas as alturas foram reconhecidas. Repita com metrônomo.'}else if(el)el.textContent='✓ Próxima: '+full(guided.notes[guided.i])+' · '+(guided.i+1)+'/'+guided.notes.length}}else{guided.streak=0;guided.wrong++}}
function stopGuided(){guided=null;stopMic();let el=$('#guided-status');if(el)el.textContent='Prática interrompida.'}
function playPiece(all){let p=PIECES[pieceIndex],a=pieceSegment*8;playSequence(all?p.notes:p.notes.slice(a,a+8),all?p.beats:p.beats.slice(a,a+8),pieceSpeed)}function recordPiece(){let p=PIECES[pieceIndex];S.sessions.push({title:p.title+' · trecho '+(pieceSegment+1),t:Date.now(),minutes:0,completed:false});S.xp+=2;save();toast('Prática de repertório registrada.');render()}
function progressPage(){let w=weak(),done=Object.keys(S.completed).length,total=S.attempts.length,first=S.attempts.filter(a=>a.ok).length;return `<h1>Sua evolução</h1><p class="muted">Resultados recentes, padrões de erros e rotina. Indicadores são estimativas pedagógicas, não avaliações profissionais.</p><div class="grid four section">${[['Nível',level()],['Aulas',`${done}/${LESSONS.length}`],['Tentativas',total],['Acerto total',total?Math.round(first/total*100)+'%':'—']].map(([a,b])=>`<div class="card"><span class="muted small">${a}</span><div class="metric">${b}</div></div>`).join('')}</div><div class="section grid"><div class="card"><h2>Domínio por habilidade</h2>${Object.entries(SKILLS).map(([k,t])=>{let p=scoreSkill(k),n=S.attempts.filter(a=>a.skill===k).length;return `<div class="lessonrow"><div style="flex:1"><strong>${t}</strong><div class="bar"><i style="width:${p??0}%"></i></div><span class="muted small">${n} registro(s)</span></div><b>${p===null?'—':p+'%'}</b></div>`}).join('')}</div><div class="card"><h2>Diagnóstico e próximos passos</h2>${w.length?w.map(x=>`<div class="callout"><strong>${SKILLS[x.k]} · ${x.v}%</strong><p>${esc(({ouvido:'Revisar intervalos por comparação de duas notas.',dedilhado:'Treinar associações de dedo e altura no explorador.',afinacao:'Sustentar notas isoladas com referência e gravar amostras.',ritmo:'Reproduzir padrões de um e dois tempos a andamento lento.',leitura:'Rever cordas soltas e linhas/espaços da clave de Sol.',tecnica:'Repetir devagar e verificar conforto com orientação.'})[x.k]||'Rever as explicações e exercícios recentes.')}</p></div>`).join(''):'<p class="muted">Ainda não há dificuldades recorrentes com amostra suficiente. São necessárias pelo menos três tentativas por habilidade.</p>'}<h3>Erros recorrentes</h3>${errorPatterns()}<div class="line"></div><h3>XP e níveis</h3><div class="metric">Nível ${level()}</div><div class="bar"><i style="width:${S.xp%100}%"></i></div><p class="muted small">${S.xp%100}/100 XP para o próximo nível. Aulas novas +25, revisões +4, exercícios +3 ou −1. A evolução pode recuar com erros nos laboratórios; a aprendizagem tem prioridade sobre o nível.</p></div></div><div class="section grid"><div class="card"><h2>Histórico</h2><div class="history">${S.sessions.length?[...S.sessions].reverse().slice(0,50).map(a=>`<div class="lessonrow"><div><strong>${esc(a.title)}</strong><span class="muted small">${fmtDate(a.t)} · ${a.minutes} min</span></div>${a.completed?'<span class="tag done">Concluída</span>':'<span class="tag">Prática</span>'}</div>`).join(''):'<div class="empty">Sem sessões registradas.</div>'}</div></div><div class="card"><h2>Diário de aprendizagem</h2><div class="history">${S.journal.length?[...S.journal].reverse().map(a=>`<div class="lessonrow"><div><strong>${esc(a.title)}</strong><p>${esc(a.note)}</p><span class="muted small">${fmtDate(a.t)}</span></div></div>`).join(''):'<div class="empty">As anotações das aulas aparecem aqui.</div>'}</div></div></div><div class="section card"><h2>Preferências e dados</h2><div class="control"><label>Nome da estudante</label><input type="text" maxlength="40" value="${esc(S.name)}" onchange="S.name=this.value.trim()||'Estudante';save();render()"></div><div class="control"><label>Tempo diário de estudo</label><select onchange="S.minutes=Number(this.value);save();render()">${[10,15,20,25,30,40,45,60].map(n=>`<option value="${n}" ${S.minutes===n?'selected':''}>${n} minutos</option>`).join('')}</select></div><div class="actions">${btn('Exportar progresso','exportData()','secondary')}<label class="btn secondary" style="cursor:pointer">Importar backup<input class="sr" type="file" accept="application/json,.json" onchange="importData(this)"></label>${btn('Zerar progresso','resetData()','secondary')}</div></div>`}
function errorPatterns(){let a={};S.attempts.filter(x=>!x.ok).forEach(x=>a[x.detail]=(a[x.detail]||0)+1);let r=Object.entries(a).sort((x,y)=>y[1]-x[1]).slice(0,5);return r.length?r.map(([t,n])=>`<div class="lessonrow"><span class="small">${esc(t)}</span><span class="tag">${n}×</span></div>`).join(''):'<p class="muted small">Nenhum erro registrado ainda.</p>'}
function exportData(){let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='archet-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importData(el){if(!el.files[0])return;try{let o=JSON.parse(await el.files[0].text());if(!o||typeof o.xp!=='number'||!Array.isArray(o.attempts)||!Array.isArray(o.sessions)||!o.completed||!Array.isArray(o.journal))throw Error();if(!confirm('Substituir o progresso atual pelo backup?'))return;S={...defaults(),...o};save();render();toast('Backup importado.')}catch{toast('Arquivo de backup inválido.')}}function resetData(){if(confirm('Apagar todo o progresso deste dispositivo? Exporte um backup antes.')){S=defaults();save();go('home')}}
function libraryPage(){const tabs=[['theory','Teoria'],['glossary','Glossário'],['coach','Professor IA'],['about','Sobre o método']];let content='';if(libraryTab==='theory')content=`<div class="card"><h2>Biblioteca de teoria</h2><p class="muted">Consulta livre, inclusive antes de liberar uma aula. As atividades do curso continuam sequenciais.</p><input id="search" class="wide" type="text" placeholder="Buscar assunto: semitom, arco, escala..." oninput="filterTheory(this.value)"><div id="theory-results">${theoryList('')}</div></div>`;if(libraryTab==='glossary')content=`<div class="card"><h2>Glossário musical</h2>${GLOSSARY.map(([t,d])=>`<div class="lessonrow"><div><strong>${esc(t)}</strong><div class="muted">${esc(d)}</div></div></div>`).join('')}</div>`;if(libraryTab==='coach'){let prompt=coachPrompt();content=`<div class="card"><h2>Professor virtual · ChatGPT</h2><p>Gere um resumo do progresso e leve para o ChatGPT. Esta integração é por contexto copiado: não usa API paga, não lê conversas automaticamente e não sincroniza respostas com o app.</p><label>Minha dúvida de hoje</label><textarea id="coach-question" placeholder="Ex.: tenho dificuldade no segundo dedo baixo."></textarea><div class="actions">${btn('Copiar contexto para ChatGPT','copyCoach()')}<a class="btn secondary" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Abrir ChatGPT ↗</a></div><details class="section"><summary>Prévia do contexto (sem dúvida)</summary><div class="callout coach">${esc(prompt)}</div></details></div>`}if(libraryTab==='about')content=`<div class="card"><h2>Sobre o Archet</h2><p>Curso original para iniciantes adultos. O método integra teoria contextualizada, visualização, escuta, compreensão, prática e reflexão. O currículo foi inspirado em abordagens pedagógicas tradicionais e modernas, sem reproduzir páginas ou exercícios protegidos.</p><h3>Referências de estudo</h3>${[['Essential Elements for Strings — Violin, Book 1','Hal Leonard · progressão de técnica e leitura.'],['Suzuki Violin School, Vol. 1','Shinichi Suzuki · escuta e repertório.'],['Le Violon : théorie et pratique','Mathieu Crickboom · método progressivo.'],['Violin Method for Beginners, Op. 6','Otakar Ševčík · padrões de dedilhado.'],['The Doflein Method, Vol. 1: The Beginning','Erich e Elma Doflein · integração de técnica e musicalidade.'],['Princípios Básicos da Música para a Juventude','Maria Luisa de Mattos Priolli · teoria musical em português.'],['Teoria da Música; Ritmo','Bohumil Med · teoria e percepção rítmica.'],['Basics','Simon Fischer · princípios técnicos e exercícios corretivos.']].map(([t,d])=>`<div class="lessonrow"><div><strong>${t}</strong><span class="muted small">${d}</span></div></div>`).join('')}<div class="callout">Este aplicativo complementa o estudo presencial. Não substitui professor, luthier ou avaliação técnica. Afinação usa estimativa de frequência e reprodução sintetizada em temperamento igual. Evite praticar com dor.</div><p class="muted small">Sem cadastro, anúncios, analytics ou API externa. Conteúdo original; partituras de melodias em domínio público são arranjos didáticos simplificados.</p></div>`;return `<h1>Biblioteca</h1><div class="tabs">${tabs.map(([id,t])=>btn(t,`libraryTab='${id}';render()`,'secondary '+(libraryTab===id?'active':''))).join('')}</div>${content}`}
function theoryList(q){let v=q.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'');return LESSONS.filter(l=>(l.title+' '+l.theory).toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(v)).map(l=>`<details class="module" style="border-bottom:1px solid var(--line);padding:12px 0"><summary><strong>${esc(l.title)}</strong></summary><p class="prose">${esc(l.theory)}</p>${l.notes.length?btn('▶ Ouvir exemplo',`playSequence(LESSONS.find(l=>l.id==='${l.id}').notes,[],60)`,'secondary small'):''}<p class="muted small">${esc(l.practice)}</p></details>`).join('')||'<p class="muted">Nenhum assunto encontrado.</p>'}function filterTheory(v){$('#theory-results').innerHTML=theoryList(v)}
function coachPrompt(){return `Atue como professor de violino para iniciante adulta, em português. Explique a teoria antes do exercício, com exemplos de nota, corda, dedilhado, ritmo e prática. Não presuma que consegue ouvir ou observar minha postura. Sugira exercícios curtos e seguros.\nNome: ${S.name}. Tempo diário: ${S.minutes} min. Aulas concluídas: ${Object.keys(S.completed).length}/${LESSONS.length}. Próxima aula: ${nextLesson()?.title||'Revisão'}.\nDesempenho recente: ${Object.entries(SKILLS).map(([k,t])=>`${t}: ${scoreSkill(k)??'sem dados'}${scoreSkill(k)===null?'':'%'}`).join('; ')}.\nDificuldades recentes: ${S.attempts.filter(x=>!x.ok).slice(-8).map(x=>x.detail).join('; ')||'sem dados'}.\nAnotações: ${S.journal.slice(-3).map(x=>x.title+': '+x.note).join('; ')||'nenhuma'}.`}
async function copyCoach(){let v=coachPrompt()+'\nDúvida: '+($('#coach-question')?.value||'Ajude-me a organizar minha próxima sessão.');try{await navigator.clipboard.writeText(v);toast('Contexto copiado. Cole no ChatGPT.')}catch{let a=document.createElement('textarea');a.value=v;document.body.append(a);a.select();try{document.execCommand('copy');toast('Contexto copiado.')}catch{toast('Selecione o texto para copiar.')}a.remove()}}
window.addEventListener('beforeunload',()=>{stopMic();if(recRecording)stopRecording()});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
